def lowestPeak(n, roads, queries):
    q = len(queries)
    ans = [-1] * q
    parent = list(range(n))
    pending = [set() for _ in range(n)]
    for j, (u, v) in enumerate(queries):
        if u == v:
            ans[j] = 0
        else:
            pending[u].add(j)
            pending[v].add(j)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b, h in sorted(roads, key=lambda e: e[2]):
        ra, rb = find(a), find(b)
        if ra == rb:
            continue
        if len(pending[ra]) < len(pending[rb]):
            ra, rb = rb, ra
        for j in pending[rb]:
            if j in pending[ra]:
                ans[j] = h
                pending[ra].discard(j)
            else:
                pending[ra].add(j)
        pending[rb] = set()
        parent[rb] = ra
    return ans
